package org.icu.sepsis.ai;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import java.util.*;import org.junit.jupiter.api.Test;
class AiDiagnosticsTest {
 @Test void syntheticServerProbeReportsTransportWithoutClaimingClinicalValidation(){var props=AiAssistServiceTest.props(true,"http://synthetic.invalid","fast","reason","embedding",1000,2);var llm=mock(LlmClient.class);var kb=mock(KnowledgeBase.class);when(kb.vectorStatus()).thenReturn("ready");when(kb.vectorCacheStatus()).thenReturn("restored");var reply=new LlmClient.Reply();reply.content="测试成功";when(llm.chat(anyString(),anyList(),anyInt(),anyBoolean(),anyInt(),anyBoolean())).thenReturn(reply);when(llm.embed(anyList(),anyInt())).thenReturn(List.of(new float[]{1,2}));var result=(Map<?,?>)new AiDiagnosticsController(props,llm,kb).check().data;assertEquals(false,result.get("patientDataSent"));assertEquals(false,result.get("clinicalValidation"));assertEquals(3,((List<?>)result.get("checks")).size());}
 @Test void disabledModelsNeverCallGateway(){var p=AiAssistServiceTest.props(false,"","","","",1000,2);var l=mock(LlmClient.class);var kb=mock(KnowledgeBase.class);when(kb.vectorStatus()).thenReturn("not_configured");when(kb.vectorCacheStatus()).thenReturn("disabled");new AiDiagnosticsController(p,l,kb).check();verifyNoInteractions(l);}

 @Test void malformedConfigurationDoesNotAbortOtherChecksOrExposeExceptionDetails(){var props=AiAssistServiceTest.props(true,"http://synthetic.invalid","fast","reason","embedding",1000,2);var llm=mock(LlmClient.class);var kb=mock(KnowledgeBase.class);when(kb.vectorStatus()).thenReturn("ready");when(kb.vectorCacheStatus()).thenReturn("restored");when(llm.chat(anyString(),anyList(),anyInt(),anyBoolean(),anyInt(),anyBoolean())).thenThrow(new IllegalArgumentException("secret-token-in-exception"));when(llm.embed(anyList(),anyInt())).thenReturn(List.of(new float[]{1,2}));var data=(Map<?,?>)new AiDiagnosticsController(props,llm,kb).check().data;var checks=(List<Map<String,Object>>)data.get("checks");assertEquals(3,checks.size());assertEquals("configuration_error",checks.get(0).get("errorKind"));assertEquals("passed",checks.get(2).get("status"));assertFalse(data.toString().contains("secret-token"));}
 @Test void unconfiguredChatIsExplicitlyReported(){var props=AiAssistServiceTest.props(false,"","","","",1000,2);var llm=mock(LlmClient.class);var kb=mock(KnowledgeBase.class);when(kb.vectorStatus()).thenReturn("not_configured");when(kb.vectorCacheStatus()).thenReturn("disabled");var data=(Map<?,?>)new AiDiagnosticsController(props,llm,kb).check().data;assertTrue(((List<Map<String,Object>>)data.get("checks")).stream().anyMatch(c->"chat".equals(c.get("kind"))&&"not_configured".equals(c.get("status"))));verifyNoInteractions(llm);}
}
